import React from "react";
import { useWeekWeatherQuery } from "../hooks/useWeather";
import {Swiper, SwiperSlide} from "swiper/react";
import { Pagination} from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";


function WeekCard({ location }) {

  const {
    data: week = { list: [] },
    isLoading: isWeekLoading,
    isError: isErrorWeek,
    error: WeekError,
  } = useWeekWeatherQuery(location);

  if (isWeekLoading) {
    return <h1> 주간 날씨 정보를 가져 오는 중...⏳</h1>;
  }
  if (isErrorWeek) {
    return <h1>{WeekError.message}</h1>;
  }

  //주간날씨데이터: 하루의 평균 온도
  const dailyTemp = week.list.reduce((acc, days) => {
    // dt._txt에서 날짜 추출(yyyy-mm-dd)
    const day = days.dt_txt.split(" ")[0];

    // 해당 날짜에 데이터 X, 초기화
    if (!acc[day]) {
      acc[day] = { total: 0, count: 0, dt_txt: days.dt_txt, icons: [] };
    }

    // 현재 day's 온도 해당 날짜 종합에 추가
    acc[day].total += days.main.temp;

    // 데이터 개수 1 증가
    acc[day].count += 1;

    // icon 받아오기
    acc[day].icons.push(days.weather[0].icon);

    return acc;
  }, {});



  // 오늘 0시 기준
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Filter
  const filteredDays = Object.keys(dailyTemp)
  .filter((day) => new Date(day) >= today)
  .sort((a ,b) => new Date(a) - new Date(b))
  .slice(0, 5);

  const dailyAverages = filteredDays.map((day) => ({
    day,
    avgTemp: dailyTemp[day].total / dailyTemp[day].count,
    dt_txt: dailyTemp[day].dt_txt,
    icons: dailyTemp[day].icons,
  }));



  return (
    <div className="week_card">
      <h2>5-Day Forecast</h2>
      <div className="week_i">
        <Swiper
          pagination={{
            dynamicBullets: true,
            clickable: true,
          }}
          modules={[Pagination]}
          slidesPerView={5}
          spaceBetween={0}
          centeredSlides={true}
          grabCursor={true}
          loop={false}
          className="mySwiper week_swiper"
        >
          {dailyAverages?.map(({ day, avgTemp, dt_txt, icons }) => (
            <SwiperSlide className="swiper_slide" key={day}>
              <div className="week_data">
                <p className="daily_date">{dt_txt.substring(5, 10)}</p>
                <img
                  src={`https://openweathermap.org/img/wn/${icons[0]}.png`}
                />
                <p className="daily_temp">{avgTemp.toFixed(0)}°</p>
              </div>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </div>
  );
}

export default WeekCard;
