import React, { useState } from "react";
import { useCityWeatherQuery } from "../hooks/useWeather";
import CityCard from "../component/CityCard";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faXmark } from "@fortawesome/free-solid-svg-icons";
import { faMagnifyingGlass } from "@fortawesome/free-solid-svg-icons";
import { useNavigate } from "react-router-dom";

function Search() {
  const [city, setCity] = useState("");
  const [searchCity, setSearchCity] = useState("");
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    if (searchCity.trim() !== "") {
      setCity(searchCity.trim());
      setSearchCity("");
    }
  };

  const handleClose = () => {
    navigate("/");
  };

  const { data, isLoading, isError, error } = useCityWeatherQuery(city);

  if (isLoading) {
    return <p>검색한 도시의 날씨 정보를 가져오는 중...</p>;
  }
  if (isError) {
    return <p>{error.message}</p>;
  }

  return (
    <div className="search">
      
      <div className="search_h">
        <FontAwesomeIcon
          icon={faXmark}
          size="lg"
          style={{ color: "#ffffff", cursor: "pointer" }}
          onClick={handleClose}
        />
        <form onSubmit={handleSubmit}>
          <input
            name="city"
            value={searchCity}
            onChange={(e) => setSearchCity(e.target.value)}
            placeholder="도시 이름을 영어로 입력하세요."
          />
          <button type="submit">
            <FontAwesomeIcon
              icon={faMagnifyingGlass}
              size="lg"
              style={{ color: "#ffffff" }}
            />
          </button>
        </form>
      </div>

      <div className="search_i">
        {data && <CityCard data={data} city={city} />}
      </div>
    </div>
  );
}

export default Search;
