import React, { useState, useEffect } from "react";
import { useWeatherQuery } from "../hooks/useWeather";
import WeatherCard from "../component/WeatherCard";
import HoursCard from "../component/HoursCard";
import WeekCard from "../component/WeekCard";

function WeatherBox() {

  const [location, setLocation] = useState({ lat: null, lon: null });
  const getCurrentLocation = () => {
    navigator.geolocation.getCurrentPosition((position) => {
      let lat = position.coords.latitude;
      let lon = position.coords.longitude;
      console.log("위치확인", { lat, lon });
      setLocation({ lat, lon });
    });
  };

  useEffect(() => {
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const lat = position.coords.latitude;
        const lon = position.coords.longitude;
        setLocation({ lat, lon });
      },
      (error) => {
        console.warn("위치 권한 없음. 기본값 사용");
        setLocation({ lat: 37.5665, lon: 126.978 });
      }
    );
  }, []);

  const {
    data: weatherData,
    isLoading: isLocationLoading,
    isError: isErrorLocation,
    error: locationError,
  } = useWeatherQuery(location);

  if (isLocationLoading) {
    return <p>정보를 가져오는 중입니다...⏳</p>;
  }
  if (isErrorLocation) {
    return <p>{locationError.message}</p>;
  }
  console.log("weatherData in WeatherBox:", weatherData);

  return (
    <div className="weather_box">
          {location && (
            <WeatherCard
              lat={location.lat}
              lon={location.lon}
              data={weatherData}
            />
          )}
        {location && <HoursCard location={location} lat={location.lat} lon={location.lon} />}
        {location&& <WeekCard location={location} lat={location.lat} lon={location.lon}/>}
      </div>
  );
}

export default WeatherBox;
