import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faBars } from "@fortawesome/free-solid-svg-icons";
import { useDailyHightLowQuery } from "../hooks/useWeather";

function WeatherCard({ lat, lon, data }) {
  const navigate = useNavigate();

  const handleBarClick = () => {
    navigate("/search");
  };

  const [currentDate, setCurrentDate] = useState("");

  const getCurrentDate = () => {
    const today = new Date();
    const week = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

    let year = today.getFullYear();
    let month = (today.getMonth() + 1).toString().padStart(2, "0");
    let date = today.getDate();
    let day = week[today.getDay()];
    let hours = today.getHours().toString().padStart(2, "0");
    let minutes = today.getMinutes().toString().padStart(2, "0");

    setCurrentDate(`${year}-${month}-${date} ${day}, ${hours}: ${minutes}`);
  };

  useEffect(() => {
    getCurrentDate();
  }, []);
  // console.log("API weahter description", location?.weather[0]?.description);

  const {
    data: dailyHighLow,
    isLoading: isDailyLoading,
    isError: isDailyError,
  } = useDailyHightLowQuery({ lat, lon });

  if (isDailyLoading) return <p>일일 예보 데이터 로딩 중...</p>;
  if (isDailyError) return <p>일일 예보 데이터 로드 오류</p>;
  if (!dailyHighLow) return <p>일일 예보 데이터 없음</p>;

  const name = data?.name || "지역정보 없음";
  const weather = data?.weather?.[0]?.main;
  const temp = data?.main?.temp?.toFixed(0);
  const icon = data?.weather?.[0]?.icon;
  const feelslike = data?.main?.feels_like.toFixed(0);
  const humidity = data?.main?.humidity;
  const speed = data?.wind?.speed.toFixed(0);

  const maxTemp = dailyHighLow.maxTemp.toFixed(0);
  const minTemp = dailyHighLow.minTemp.toFixed(0);

  console.log("날씨 데이터 확인:", { name, temp, icon });
  console.log("전체 data 확인", data);

  return (
    <div className="weather_card">
      <div className="wc_header">
        <FontAwesomeIcon
          className="bar"
          icon={faBars}
          size="lg"
          style={{ color: "#ffffff", cursor: "pointer" }}
          onClick={handleBarClick}
        />
        <h2>{name}</h2>
      </div>

      <p className="date">{currentDate}</p>

      <div className="main_info">
        <picture>
          {icon && (
            <img
              src={`https://openweathermap.org/img/wn/${icon}@2x.png`}
              alt="날씨 아이콘"
            />
          )}
        </picture>
        <p className="temp">{temp}°</p>
        <p className="weather">{weather}</p>
        <p className="feels_like">체감온도: {feelslike}℃</p>
      </div>
      <div className="sub_info">
        <div className="temp_info">
          <p>최고: {maxTemp}°</p>
          <p>최저: {minTemp}°</p>
        </div>
        <div className="other_info">
          <p>습도: {humidity}%</p>
          <p>풍속: {speed}m/s</p>
        </div>
      </div>
    </div>
  );
}

export default WeatherCard;
