import React from "react";
import { useHourWeatherQuery } from "../hooks/useWeather";
import { Swiper, SwiperSlide } from "swiper/react";
import { Pagination } from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";

function HoursCard({ lat, lon }) {
  const { data: hour } = useHourWeatherQuery({ lat, lon });

  return (
    <div className="hour_card">
      <h2>Time-of-Day Forecast</h2>
      <div className="hour_i">
        <Swiper
          pagination={{
            dynamicBullets: true,
            clickable: true,
          }}
          modules={[Pagination]}
          slidesPerView={5}
          spaceBetween={0}
          centeredSlides={true}
          grabCursor={true}
          loop={false}
          className="mySwiper hour_swiper"
        >
          {hour?.slice(1, 6).map((item, idx) => (
            <SwiperSlide key={item.dt_txt}>
              <div className="hour_data">
                <p className="hour_time">{item.dt_txt.substring(11, 16)}</p>
                <img
                  src={`https://openweathermap.org/img/wn/${item.weather[0].icon}.png`}
                  alt={item.weather[0].description}
                  className="icon"
                />
                <p className="hour_temp">{item.main.temp.toFixed(0)}°</p>
              </div>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </div>
  );
}

export default HoursCard;
