import { useDailyHighLowByCityQuery } from "../hooks/useWeather";

function CityCard({ data, city }) {
  const { data: dailyHighLow } = useDailyHighLowByCityQuery(city);

  const maxTemp = dailyHighLow?.maxTemp?.toFixed(0);
  const minTemp = dailyHighLow?.minTemp?.toFixed(0);

  const name = data?.name || "지역정보 없음";
  const weather = data?.weather?.[0]?.main;
  const temp = data?.main?.temp?.toFixed(0);
  const icon = data?.weather?.[0]?.icon;
  const humidity = data?.main?.humidity;
  const speed = data?.wind?.speed.toFixed(0);
  const feelslike = data?.main?.feels_like.toFixed(0);

  return (
    <div className="city_card">
      <h2 className="city_name">{name}</h2>

      <div className="city_main">
        <picture>
          {data?.weather && data.weather[0] && (
            <img
              src={`https://openweathermap.org/img/wn/${icon}@2x.png`}
              alt="날씨 아이콘"
            />
          )}
        </picture>
        <p className="city_temp">{temp}°</p>
        <p className="city_weather">{weather}</p>
        <p className="city_feels_like">체감온도: {feelslike}°</p>
      </div>

      <div className="city_sub">
        {dailyHighLow && (
          <div className="city_temp_info">
            <p>최고: {dailyHighLow.maxTemp}°</p>
            <p>최저: {dailyHighLow.minTemp}°</p>
          </div>
        )}
        <div className="city_other">
          <p>습도: {humidity}%</p>
          <p>풍속: {speed}m/s</p>
        </div>
      </div>
    </div>
  );
}

export default CityCard;
